import os
import numpy as np

# Get the working directory
working_dir = os.path.join(os.getcwd(), "working")

# Load the experiment data from the npy file
experiment_data = np.load(
    os.path.join(working_dir, "experiment_data.npy"), allow_pickle=True
).item()


# Function to print the extracted metrics with clear labels
def print_metrics(data):
    for ablation_name, datasets in data.items():
        for dataset_name, results in datasets.items():
            print(f"Dataset: {dataset_name}")
            for metric_type, metrics in results["metrics"].items():
                if metrics:
                    print(f"Final Test Accuracy: {metrics[-1]:.2f}")
                else:
                    print("No metrics found.")


# Execute the metrics extraction and printing
print_metrics(experiment_data)
